"""Text Similarity Analyzer - generates sample texts and compares them."""

# Build a word pool and some sentences from it
WORDS = (
    "swift", "ancient", "tiny", "vast", "bold", "quiet", "fierce", "gentle",
    "moon", "star", "river", "mountain", "cloud", "ocean", "forest", "garden",
    "whisper", "shout", "dream", "wander", "glow", "sparkle", "drift", "sail"
)
SENTENCES = [
    "A swift river winds through the quiet forest at dawn.",
    "The ancient moon watches over tiny stars drifting on the vast ocean.",
    "Bold whispers travel through the vast forest at midnight.",
    "Gentle clouds sail over the garden where a tiny mountain sleeps.",
    "A fierce dragon glows in the dark, watching the quiet forest drift.",
    "The tiny river sparkles as it wanders toward the bold moon.",
    "Vast clouds whisper to the garden where ancient mountains sleep.",
    "A quiet star drifts above the garden, near the tiny, gentle moon.",
]

def similarity(text1, text2):
    """Jaccard similarity between two sentences (0.0 to 1.0)."""
    # Normalize: lowercase, strip punctuation, split on spaces
    normalize = lambda s: s.lower().translate(str.maketrans('', '', '.,!?;:'))
    words1 = set(normalize(text1).split())
    words2 = set(normalize(text2).split())
    if not words1 and not words2:
        return 1.0
    union = words1 | words2
    inter = words1 & words2
    return len(inter) / len(union)

def generate_sentence():
    """Pretend to create a fresh sentence by mixing words."""
    length = 3 + (len(WORDS) % 5)  # 3 to 7 words
    return " ".join(random.sample(WORDS, length))

# Import random for some variety (standard library, not blocking)
import random

def main():
    # Clear the terminal once
    print('\033[2J\033[H', end='')

    # ASCII header
    print('\033[1;35m╔════════════════════════════════════════════════════════════╗')
