    print('\033[1;35m╚════════════════════════════════════════════════════════════╝\033[0m')

    # Show the sample sentences
    print('\033[1;33m───────── GENERATED SAMPLE TEXTS ──────────\033[0m')
    for i, s in enumerate(SENTENCES):
        print(f'\033[1;35m{chr(149)+str(i+1)}\033[0m  {s}')

    # Compute pairwise similarities
    print('\033[1;33m───────── SIMILARITY RESULTS ──────────\033[0m')
    for i, t1 in enumerate(SENTENCES):
        for t2 in SENTENCES[i+1:]:
            score = similarity(t1, t2)
            color = '\033[1;32m' if score > 0.4 else '\033[1;34m'
            print(f'\033[1;35m{chr(149)+str(i+1)}\033[0m ─ {chr(149)+str(i+2)}\033[0m │\033[1;33m{t1[:20]}…\033[0m vs |\033[1;33m{t2[:20]}…\033[0m\033[0m')
            print(f'\033[{color}Jaccard = {score:.3f}\033[0m')

    # Verify that self-similarity is essentially 1.0
    print('\033[1;33m───────── VERIFICATION ──────────\033[0m')
    self_sim = similarity(SENTENCES[0], SENTENCES[0])
    verdict = 'PASS' if self_sim >= 0.99 else 'FAIL'
    print(f'\033[1;35mVerdict: {verdict}\033[0m (self-similarity = {self_sim:.4f})')

    # Generate a few more "on the fly" sentences
    print('\033[1;33m───────── MORE GENERATED TEXTS ──────────\033[0m')
    for j in range(3):
        fresh = generate_sentence()
        fresh_sim = similarity(fresh, SENTENCES[j])
        print(f'\033[1;35m{chr(149)+str(j+1)}\033[0m  {fresh}')
